class RmodNotFound(Exception):
    """
    Raised when information about radio modules could not be found.
    """
    pass


class DifferentRmodCount(Exception):
    """
    Raised when number of radio modules is inconsistent.
    """
    pass


class ProductCodesDoNotMatch(Exception):
    """
    Raised when product codes for radio modules do not match.
    """
    pass


class DifferentSmodCount(Exception):
    """
    Raised when SMOD serial numbers values are different length.
    """
    pass


class DifferentSmodsDetected(Exception):
    """
    Raised when SMOD serial numbers values are inconsistent.
    """
    pass


class SerialNumbersAndProductCodesDoNotMatch(Exception):
    """
    Raised when serial numbers and product codes do not match.
    """
    pass
